messages.content:
Game edukasi Endless Runner "Energy Sort Run" dengan tema Clean Modern, kesulitan Santai, dan mekanik pemilahan sumber energi terbarukan vs tidak terbarukan. Asumsi: item belajar dipetakan ke bentuk kategori (bukan kuis), dan rintangan dibuat sempit agar sesuai tempo Santai.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "energy-sort-run", title: "Energy Sort Run", seed: "energy-sort-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Ilmu Pengetahuan Alam",
    concept: "Sumber energi terbarukan dan tidak terbarukan",
    objectives: ["Mengelompokkan sumber energi berdasarkan sifat ketersediaannya di alam"],
    misconceptions: ["Energi terbarukan berarti energinya tidak akan pernah habis sama sekali"],
    mode: "category",
    categories: [
      { id: "terbarukan",      label: "Terbarukan",      color: "#3FA34D" },
      { id: "tidak-terbarukan", label: "Tidak Terbarukan", color: "#E5484D" }
    ],
    items: [
      { id: "sinar-matahari", label: "Sinar matahari", category: "terbarukan",      explain: "Terus tersedia dan diperbarui oleh alam setiap hari." },
      { id: "angin",          label: "Angin",          category: "terbarukan",      explain: "Terbentuk terus-menerus oleh pemanasan atmosfer." },
      { id: "aliran-air",     label: "Aliran air",     category: "terbarukan",      explain: "Siklus air diperbarui oleh hujan dan gravitasi." },
      { id: "batu-bara",      label: "Batu bara",      category: "tidak-terbarukan", explain: "Terbentuk dari fosil selama jutaan tahun." },
      { id: "minyak-bumi",    label: "Minyak bumi",    category: "tidak-terbarukan", explain: "Cadangan fosil yang terbatas dan sangat lambat terbentuk." },
      { id: "gas-alam",       label: "Gas alam",       category: "tidak-terbarukan", explain: "Sumber fosil yang akan habis jika terus dipakai." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 5, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 300, maxSpeed: 600, accel: 4 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 20, speed: 20 }
  }
});
// END_OF_MANIFEST
```
